<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { AlertCircle, CheckSquare, ChevronLeft, ChevronRight, CreditCard, Download, Edit3, Eye, FileDown, FileImage, Filter, History, LoaderCircle, MessageSquare, PackagePlus, Plus, RefreshCw, Search, Trash2, X } from 'lucide-vue-next';
import api, { apiError, apiErrors, apiMessage } from '../services/api';
import { formatColumn, timezoneFor, toDateInput, toDateTimeInput } from '../utils/datetime';
import { useAuthStore } from '../stores/auth';
const props = defineProps({ moduleKey: { type: String, required: true } }); const auth = useAuthStore(); const route = useRoute();
const schema = ref(null); const records = ref([]); const meta = ref({ current_page: 1, last_page: 1, total: 0 }); const lookups = ref({}); const loading = ref(true); const saving = ref(false); const error = ref(''); const formError = ref(''); const fieldErrors = ref({}); const drawer = ref(false); const mode = ref('create'); const selected = ref(null); const page = ref(1); const search = ref(''); const status = ref(''); const from = ref(''); const to = ref(''); const form = reactive({}); const workflow = ref({}); const workflowBusy = ref(false); const paymentOpen = ref(false); const movementOpen = ref(false); const payment = reactive({ amount: '', paid_at: toDateInput(new Date().toISOString()), payment_method: 'bank', reference_number: '' }); const movement = reactive({ movement_type: 'stock_in', quantity: '', movement_date: toDateInput(new Date().toISOString()), unit_price: '', notes: '' }); const newChecklist = ref(''); const newComment = ref('');
// Template ref to the record form. The save button must call requestSubmit() through this
// ref: `document` inside a <script setup> template resolves to the Vue module namespace,
// not the browser global, so a getElementById lookup there throws.
const recordForm = ref(null);
const saveRecord = () => recordForm.value?.requestSubmit();
const title = computed(() => schema.value?.label || 'Records'); const formTitle = computed(() => mode.value === 'edit' ? 'Edit record' : 'New record'); const hasStatus = computed(() => schema.value?.columns?.includes('status')); const canCreate = computed(() => auth.can(`${schema.value?.prefix || props.moduleKey}.create`)); const canEdit = computed(() => auth.can(`${schema.value?.prefix || props.moduleKey}.edit`)); const canDelete = computed(() => auth.can(`${schema.value?.prefix || props.moduleKey}.delete`));
const timezone = computed(() => timezoneFor(auth.user)); const money = (value) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(value || 0)); const human = (value) => String(value ?? '—').replaceAll('-', ' ').replace(/\b\w/g, (c) => c.toUpperCase());
const display = (record, column) => { const value = record[column] ?? record[column.replace(/_id$/, '')]; if (column.includes('amount') || column.includes('cost') || column.includes('price') || ['premium','monthly_rent','coverage_amount'].includes(column)) return money(value); if (typeof value === 'object' && value) return value.name || value.title || value.vehicle_number || human(value.id); if (typeof value === 'boolean') return value ? 'Yes' : 'No'; if (typeof value === 'string' && (value.includes('T') || /^\d{4}-\d{2}-\d{2}/.test(value))) return formatColumn(column, value, timezone.value); return human(value); };
const statusTone = (value) => ['paid','completed','active','healthy','excellent','good','new'].includes(String(value)) ? 'green' : ['overdue','cancelled','expired','sick','urgent','high'].includes(String(value)) ? 'red' : ['due','pending','scheduled','in-progress','medium','needs-attention'].includes(String(value)) ? 'amber' : 'blue';
const optionsFor = (field) => field.options?.length ? field.options.map((value) => ({ id: value, label: human(value) })) : (lookups.value[field.source] || []);
const setForm = (record = {}) => { Object.keys(form).forEach((key) => delete form[key]); (schema.value?.fields || []).forEach((field) => { let value = record[field.name] ?? (field.type === 'checkbox' ? 0 : ''); if (field.type === 'date' && value) value = toDateInput(value, timezone.value); if (field.type === 'datetime-local' && value) value = toDateTimeInput(value, timezone.value); form[field.name] = value; }); };
const loadLookups = async () => { const sources = [...new Set((schema.value?.fields || []).map((field) => field.source).filter(Boolean))]; await Promise.all(sources.map(async (source) => { try { lookups.value[source] = (await api.get(`/lookups/${source}`)).data.data; } catch { lookups.value[source] = []; } })); };
const cacheKey = () => `home-erp:module:${props.moduleKey}:${JSON.stringify({ page: page.value, search: search.value, status: status.value, from: from.value, to: to.value })}`;
const clearCache = () => { for (const key of Object.keys(sessionStorage)) if (key.startsWith(`home-erp:module:${props.moduleKey}:`)) sessionStorage.removeItem(key); };
const load = async (force = false) => { const key = cacheKey(); if (!force) { try { const cached = JSON.parse(sessionStorage.getItem(key)); if (cached && Date.now() - cached.saved_at < 45000) { schema.value = cached.schema; records.value = cached.records; meta.value = cached.meta; loading.value = false; return; } } catch {} } loading.value = true; error.value = ''; try { const { data } = await api.get(`/modules/${props.moduleKey}`, { params: { page: page.value, per_page: 15, search: search.value || undefined, status: status.value || undefined, from: from.value || undefined, to: to.value || undefined } }); if (data.schema) schema.value = data.schema; records.value = data.data; meta.value = data.meta; try { sessionStorage.setItem(key, JSON.stringify({ saved_at: Date.now(), schema: schema.value, records: records.value, meta: meta.value })); } catch {} } catch (e) { try { sessionStorage.removeItem(key); } catch {} error.value = apiError(e); } finally { loading.value = false; } };
const applyFilters = () => { page.value = 1; load(); }; const reset = () => { search.value = ''; status.value = ''; from.value = ''; to.value = ''; applyFilters(); };
const ensureLookups = async () => { if (Object.keys(lookups.value).length || !(schema.value?.fields || []).some((field) => field.source)) return; await loadLookups(); };
const openCreate = async () => { await ensureLookups(); mode.value = 'create'; selected.value = null; formError.value = ''; fieldErrors.value = {}; setForm(); drawer.value = true; };
const openEdit = async (record) => { await ensureLookups(); mode.value = 'edit'; selected.value = record; formError.value = ''; fieldErrors.value = {}; setForm(record); drawer.value = true; };
const openView = async (record) => { try { workflow.value = {}; if (props.moduleKey === 'tasks') { const response = (await api.get(`/tasks/${record.id}/details`)).data; selected.value = response.data; workflow.value = response.data; } else if (props.moduleKey === 'assets') { const response = (await api.get(`/assets/${record.id}/history`)).data; selected.value = response.asset; workflow.value = response; } else if (props.moduleKey === 'vehicles') { const response = (await api.get(`/vehicles/${record.id}/history`)).data; selected.value = response.vehicle; workflow.value = response; } else { const response = await api.get(`/modules/${props.moduleKey}/${record.id}`); // The record is wrapped in { data: { ... } }; without the extra unwrap the drawer shows an object with no fields and looks empty.
 selected.value = response.data?.data ?? null; } mode.value = 'view'; drawer.value = true; } catch (e) { error.value = apiError(e); } };
const closeDrawer = () => { drawer.value = false; selected.value = null; };
// PHP only parses multipart/form-data for POST, so a multipart PUT arrives with an empty body.
// Send JSON when there is no upload, and use method spoofing (POST + _method=PUT) when there is.
const hasFileUpload = (fields) => fields.some((field) => field.type === 'file' && form[field.name]?.[0]);
const submit = async () => {
  saving.value = true; formError.value = ''; fieldErrors.value = {};
  const fields = schema.value?.fields || [];
  const withFile = mode.value !== 'create' && hasFileUpload(fields);
  try {
    if (mode.value === 'create' || withFile) {
      const body = new FormData();
      fields.forEach((field) => {
        const value = form[field.name];
        if (field.type === 'file') { if (value?.[0]) body.append(field.name, value[0]); }
        else if (field.type === 'checkbox') body.append(field.name, value ? 1 : 0);
        else if (value !== '' && value !== null && value !== undefined) body.append(field.name, value);
      });
      // A super admin writes into whichever family is selected in the sidebar.
      if (auth.isSuperAdmin && auth.activeHouseholdId) body.append('household_id', auth.activeHouseholdId);
      if (mode.value === 'edit') { body.append('_method', 'PUT'); await api.post(`/modules/${props.moduleKey}/${selected.value.id}`, body); }
      else await api.post(`/modules/${props.moduleKey}`, body);
    } else {
      const payload = {};
      fields.forEach((field) => {
        if (field.type === 'file') return;
        const value = form[field.name];
        payload[field.name] = field.type === 'checkbox' ? (value ? 1 : 0) : (value === '' ? null : value);
      });
      if (auth.isSuperAdmin && auth.activeHouseholdId) payload.household_id = auth.activeHouseholdId;
      await api.put(`/modules/${props.moduleKey}/${selected.value.id}`, payload);
    }
    closeDrawer(); clearCache(); await load(true);
  } catch (e) {
    // Show a readable summary plus an inline message under each field that failed.
    fieldErrors.value = apiErrors(e);
    formError.value = apiMessage(e);
  } finally { saving.value = false; }
};
const remove = async (record) => { if (!window.confirm('Delete this record?')) return; try { await api.delete(`/modules/${props.moduleKey}/${record.id}`); clearCache(); await load(true); } catch (e) { error.value = apiError(e); } };
const exportReport = async (format) => { try { const response = await api.get(`/reports/export/${props.moduleKey}/${format}`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = `${props.moduleKey}-report.${format === 'excel' ? 'xlsx' : 'pdf'}`; link.click(); URL.revokeObjectURL(url); } catch (e) { error.value = apiError(e); } };
const openPayment = (record) => { selected.value = record; payment.amount = record.amount; payment.paid_at = toDateInput(new Date().toISOString(), timezone.value); payment.payment_method = 'bank'; payment.reference_number = ''; paymentOpen.value = true; };
const submitPayment = async () => { workflowBusy.value = true; error.value = ''; try { await api.post(`/bills/${selected.value.id}/pay`, payment); paymentOpen.value = false; clearCache(); await load(true); } catch (e) { error.value = apiError(e); } finally { workflowBusy.value = false; } };
const openMovement = (record, type = 'stock_in') => { selected.value = record; movement.movement_type = type; movement.quantity = ''; movement.movement_date = toDateInput(new Date().toISOString(), timezone.value); movement.unit_price = record.purchase_price || ''; movement.notes = ''; movementOpen.value = true; };
const submitMovement = async () => { workflowBusy.value = true; error.value = ''; try { await api.post(`/inventory/${selected.value.id}/movement`, movement); movementOpen.value = false; clearCache(); await load(true); } catch (e) { error.value = apiError(e); } finally { workflowBusy.value = false; } };
const openFile = async (kind) => { if (!selected.value?.id) return; try { const response = await api.get(`/documents/${selected.value.id}/${kind}`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); if (kind === 'download') { const link = document.createElement('a'); link.href = url; link.download = selected.value.original_name || 'home-erp-document'; link.click(); } else { window.open(url, '_blank', 'noopener'); } setTimeout(() => URL.revokeObjectURL(url), 60000); } catch (e) { error.value = apiError(e); } };
const addChecklist = async () => { if (!newChecklist.value.trim()) return; try { await api.post(`/tasks/${selected.value.id}/checklist`, { label: newChecklist.value.trim() }); newChecklist.value = ''; await openView(selected.value); } catch (e) { error.value = apiError(e); } };
const addComment = async () => { if (!newComment.value.trim()) return; try { await api.post(`/tasks/${selected.value.id}/comments`, { body: newComment.value.trim() }); newComment.value = ''; await openView(selected.value); } catch (e) { error.value = apiError(e); } };
watch(() => props.moduleKey, async () => { page.value = 1; lookups.value = {}; clearCache(); await load(true); });
onMounted(async () => { try { await load(); if (route.params.record) await openView({ id: route.params.record }); } catch (e) { error.value = apiError(e); } });
</script>
<template>
    <div class="mx-auto max-w-[1600px] space-y-5 fade-up"><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="eyebrow">Module workspace</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">{{ title }}</h1><p class="mt-1 text-sm text-[#86ada3]">Search, filter, and keep your household records current.</p></div><div class="flex flex-wrap gap-2"><button class="btn-secondary" @click="exportReport('excel')"><Download :size="15" /> Excel</button><button class="btn-secondary" @click="exportReport('pdf')"><Download :size="15" /> PDF</button><button v-if="canCreate" class="btn-primary" @click="openCreate"><Plus :size="16" /> Add {{ title.replace(/s$/, '') }}</button></div></div><p v-if="error" class="rounded-xl border border-rose-300/20 bg-rose-400/10 px-4 py-3 text-sm text-rose-200">{{ error }}</p>
        <section class="panel p-4"><div class="flex flex-col gap-3 lg:flex-row lg:items-center"><div class="relative flex-1"><Search :size="16" class="absolute left-3 top-1/2 -translate-y-1/2 text-[#5d887c]"/><input v-model="search" class="field pl-9" placeholder="Search records…" @keyup.enter="applyFilters"/></div><div class="flex flex-wrap gap-2"><select v-if="hasStatus" v-model="status" class="field min-w-[140px]"><option value="">All statuses</option><option v-for="option in schema?.fields?.find((field) => field.name === 'status')?.options || []" :key="option" :value="option">{{ human(option) }}</option></select><input v-model="from" type="date" class="field w-auto" title="From date"/><input v-model="to" type="date" class="field w-auto" title="To date"/><button class="btn-secondary" title="Apply filters" @click="applyFilters"><Filter :size="15" /></button><button class="icon-btn" title="Reset filters" @click="reset"><RefreshCw :size="15" /></button></div></div></section>
        <section class="panel overflow-hidden"><div class="flex items-center justify-between border-b border-emerald-100/10 px-4 py-3 sm:px-5"><p class="text-xs text-[#7da99c]">{{ meta.total }} record<span v-if="meta.total !== 1">s</span> · Page {{ meta.current_page }} of {{ meta.last_page }}</p><span v-if="loading" class="flex items-center gap-2 text-xs text-emerald-200/70"><LoaderCircle :size="14" class="animate-spin" /> Loading</span></div><div v-if="loading && !records.length" class="space-y-2 p-4"><div v-for="i in 7" :key="i" class="h-12 rounded-xl skeleton"></div></div><div v-else-if="!records.length" class="flex flex-col items-center justify-center px-5 py-20 text-center"><div class="flex h-14 w-14 items-center justify-center rounded-2xl bg-emerald-300/10 text-emerald-200"><Search :size="22" /></div><h3 class="mt-4 font-semibold">No records found</h3><p class="mt-1 text-sm text-[#719b8e]">Try a different search or add the first {{ title.toLowerCase() }} record.</p><button v-if="canCreate" class="btn-primary mt-5" @click="openCreate"><Plus :size="15" /> Create record</button></div><div v-else class="overflow-x-auto"><table class="w-full min-w-[720px] text-left text-sm"><thead class="text-[10px] uppercase tracking-[.14em] text-[#679689]"><tr><th v-for="column in schema?.columns" :key="column" class="whitespace-nowrap px-5 py-3 font-bold">{{ human(column) }}</th><th class="px-5 py-3"></th></tr></thead><tbody><tr v-for="record in records" :key="record.id" class="table-row"><td v-for="column in schema?.columns" :key="column" class="whitespace-nowrap px-5 py-3.5 text-[#c1e4d6]"><span v-if="column === 'status' || column === 'priority' || column === 'condition' || column === 'health_status'" class="badge" :class="`badge-${statusTone(record[column])}`">{{ human(record[column]) }}</span><span v-else>{{ display(record, column) }}</span></td><td class="whitespace-nowrap px-5 py-3 text-right"><button v-if="moduleKey === 'bills' && record.status !== 'paid' && canEdit" class="icon-btn mr-1 h-8 w-8 text-emerald-200" title="Record payment" @click="openPayment(record)"><CreditCard :size="14" /></button><button v-if="moduleKey === 'inventory' && canEdit" class="icon-btn mr-1 h-8 w-8 text-emerald-200" title="Stock in" @click="openMovement(record, 'stock_in')"><PackagePlus :size="14" /></button><button v-if="moduleKey === 'inventory' && canEdit" class="icon-btn mr-1 h-8 w-8 text-amber-200" title="Stock out" @click="openMovement(record, 'stock_out')"><PackagePlus :size="14" class="rotate-180" /></button><button class="icon-btn mr-1 h-8 w-8" title="View" @click="openView(record)"><Eye :size="14" /></button><button v-if="canEdit" class="icon-btn mr-1 h-8 w-8" title="Edit" @click="openEdit(record)"><Edit3 :size="14" /></button><button v-if="canDelete" class="icon-btn h-8 w-8 text-rose-200/70" title="Delete" @click="remove(record)"><Trash2 :size="14" /></button></td></tr></tbody></table></div><div v-if="meta.last_page > 1" class="flex items-center justify-between border-t border-emerald-100/10 px-4 py-3"><button class="icon-btn h-8 w-8" :disabled="page <= 1" @click="page--; load()"><ChevronLeft :size="15" /></button><span class="text-xs text-[#719b8e]">{{ meta.current_page }} / {{ meta.last_page }}</span><button class="icon-btn h-8 w-8" :disabled="page >= meta.last_page" @click="page++; load()"><ChevronRight :size="15" /></button></div></section>
        <Teleport to="body"><div v-if="drawer" class="fixed inset-0 z-[70] flex justify-end"><div class="absolute inset-0 bg-black/65 backdrop-blur-sm" @click="closeDrawer"></div><aside class="glass relative z-10 flex h-full w-full max-w-[480px] flex-col overflow-hidden rounded-l-[1.5rem] border-l border-emerald-100/15"><div class="flex items-center justify-between border-b border-emerald-100/10 px-4 py-3"><div><p class="eyebrow">{{ mode === 'view' ? 'Record details' : mode === 'edit' ? 'Edit record' : 'New record' }}</p><h2 class="mt-1 text-xl font-semibold">{{ mode === 'view' ? (selected?.name || selected?.title || title) : formTitle }}</h2></div><button class="icon-btn" @click="closeDrawer"><X :size="17" /></button></div><div class="flex-1 overflow-y-auto p-4"><div v-if="mode === 'view'" class="space-y-3"><div v-for="field in schema?.fields" :key="field.name" class="rounded-xl border border-emerald-100/10 bg-[#082b27] p-3"><p class="text-[10px] font-bold uppercase tracking-[.14em] text-[#679689]">{{ field.label }}</p><p class="mt-1 break-words text-sm text-[#d6f4e6]">{{ display(selected || {}, field.name) }}</p></div><div v-if="moduleKey === 'documents' && selected?.has_file" class="rounded-xl border border-amber-200/20 bg-amber-300/5 p-3"><div class="flex items-center gap-2 text-xs text-amber-100"><FileImage :size="15"/><span class="flex-1">Secure file attached</span><button class="icon-btn h-8 w-8" title="Preview" @click="openFile('preview')"><FileImage :size="14"/></button><button class="icon-btn h-8 w-8" title="Download" @click="openFile('download')"><FileDown :size="14"/></button></div></div><div v-if="moduleKey === 'tasks'" class="space-y-4 rounded-xl border border-emerald-100/10 bg-[#082b27] p-4"><div><div class="flex items-center gap-2 text-sm font-semibold"><CheckSquare :size="15" class="text-emerald-200"/> Checklist</div><div class="mt-2 space-y-2"><div v-for="item in workflow.checklist" :key="item.id" class="flex items-center gap-2 text-xs text-[#bde4d3]"><span class="h-2 w-2 rounded-full" :class="item.is_completed ? 'bg-emerald-300' : 'bg-[#527d71]' "></span>{{ item.label }}</div><span v-if="!workflow.checklist?.length" class="text-xs text-[#719b8e]">No checklist items yet.</span></div><div class="mt-3 flex gap-2"><input v-model="newChecklist" class="field" placeholder="Add checklist item" @keyup.enter="addChecklist"/><button class="icon-btn" @click="addChecklist"><Plus :size="14"/></button></div></div><div><div class="flex items-center gap-2 text-sm font-semibold"><MessageSquare :size="15" class="text-cyan-200"/> Comments</div><div class="mt-2 space-y-2"><div v-for="comment in workflow.comments" :key="comment.id" class="rounded-lg bg-[#0c3831] p-2 text-xs text-[#c5e9da]"><strong>{{ comment.user?.name || 'Member' }}</strong> {{ comment.body }}</div><span v-if="!workflow.comments?.length" class="text-xs text-[#719b8e]">No comments yet.</span></div><div class="mt-3 flex gap-2"><input v-model="newComment" class="field" placeholder="Write a comment" @keyup.enter="addComment"/><button class="icon-btn" @click="addComment"><MessageSquare :size="14"/></button></div></div></div><div v-if="moduleKey === 'assets'" class="rounded-xl border border-emerald-100/10 bg-[#082b27] p-4"><div class="flex items-center gap-2 text-sm font-semibold"><History :size="15" class="text-amber-200"/> Maintenance history</div><div class="mt-3 space-y-2"><div v-for="item in workflow.maintenance_history" :key="item.id" class="flex justify-between gap-3 text-xs text-[#c5e9da]"><span>{{ item.title }}</span><span class="text-[#719b8e]">{{ human(item.status) }} · {{ item.completion_date || 'Scheduled' }}</span></div><span v-if="!workflow.maintenance_history?.length" class="text-xs text-[#719b8e]">No maintenance history.</span></div></div><div v-if="moduleKey === 'vehicles'" class="rounded-xl border border-emerald-100/10 bg-[#082b27] p-4"><div class="flex items-center gap-2 text-sm font-semibold"><History :size="15" class="text-sky-200"/> Vehicle history</div><div class="mt-3 grid gap-2 text-xs text-[#c5e9da] sm:grid-cols-2"><div><p class="mb-1 font-semibold text-[#8eb8aa]">Services</p><p v-for="item in workflow.services" :key="item.id">{{ item.service_date }} · {{ item.service_type || 'Service' }}</p></div><div><p class="mb-1 font-semibold text-[#8eb8aa]">Expenses</p><p v-for="item in workflow.expenses" :key="item.id">{{ item.expense_date }} · {{ money(item.amount) }}</p></div></div></div></div><form v-else id="record-form" ref="recordForm" class="grid grid-cols-1 gap-3 sm:grid-cols-2" @submit.prevent="submit"><div v-for="field in schema?.fields" :key="field.name" class="sm:col-span-2" :class="field.type === 'textarea' ? 'sm:col-span-2' : ''"><label class="label">{{ field.label }} <span v-if="field.required" class="text-rose-300">*</span></label><textarea v-if="field.type === 'textarea'" v-model="form[field.name]" class="field min-h-24" :required="field.required"></textarea><select v-else-if="field.type === 'select'" v-model="form[field.name]" class="field" :required="field.required"><option value="">{{ field.source ? 'Select…' : 'Select…' }}</option><option v-for="option in optionsFor(field)" :key="option.id" :value="option.id">{{ option.label }}</option></select><label v-else-if="field.type === 'checkbox'" class="flex cursor-pointer items-center gap-2 rounded-xl border border-emerald-100/10 bg-[#062421] px-3 py-2.5 text-sm text-[#a4cabe]"><input v-model="form[field.name]" type="checkbox" class="h-4 w-4 accent-emerald-300"/> Enabled</label><input v-else-if="field.type === 'file'" type="file" class="field file:mr-3 file:rounded-lg file:border-0 file:bg-emerald-300/15 file:px-3 file:py-1.5 file:text-xs file:text-emerald-100" :accept="field.accept"/><input v-else v-model="form[field.name]" :type="field.type === 'number' ? 'number' : field.type === 'date' ? 'date' : field.type === 'datetime-local' ? 'datetime-local' : field.type === 'email' ? 'email' : 'text'" class="field" :class="fieldErrors[field.name] ? 'border-rose-400/70 ring-1 ring-rose-400/40' : ''" :step="field.step" :required="field.required"/><p v-if="fieldErrors[field.name]" class="mt-1.5 flex items-start gap-1 text-[11px] text-rose-200"><AlertCircle :size="12" class="mt-0.5 shrink-0" />{{ fieldErrors[field.name] }}</p></div><p v-if="formError" class="sm:col-span-2 flex items-start gap-2 rounded-xl border border-rose-300/30 bg-rose-400/10 px-3 py-2.5 text-xs text-rose-100"><AlertCircle :size="14" class="mt-0.5 shrink-0" /><span>{{ formError }}</span></p></form></div><div v-if="mode !== 'view'" class="flex justify-end gap-2 border-t border-emerald-100/10 px-5 py-4"><button class="btn-secondary" @click="closeDrawer">Cancel</button><button class="btn-primary" :disabled="saving" @click="saveRecord"><LoaderCircle v-if="saving" :size="15" class="animate-spin" />{{ saving ? 'Saving…' : 'Save record' }}</button></div></aside></div></Teleport>
        <Teleport to="body"><div v-if="paymentOpen" class="fixed inset-0 z-[80] flex items-center justify-center p-4"><div class="absolute inset-0 bg-black/70 backdrop-blur-sm" @click="paymentOpen = false"></div><form class="glass relative z-10 w-full max-w-md rounded-2xl p-5" @submit.prevent="submitPayment"><div class="flex items-center justify-between"><div><p class="eyebrow">Bill workflow</p><h2 class="mt-1 text-xl font-semibold">Record payment</h2></div><button type="button" class="icon-btn" @click="paymentOpen = false"><X :size="16"/></button></div><p class="mt-3 text-xs text-[#8eb8aa]">{{ selected?.name }} · {{ money(payment.amount) }}</p><div class="mt-5 space-y-4"><div><label class="label">Amount</label><input v-model="payment.amount" class="field" type="number" min="0.01" step="0.01" required/></div><div><label class="label">Paid on</label><input v-model="payment.paid_at" class="field" type="date" required/></div><div><label class="label">Payment method</label><select v-model="payment.payment_method" class="field"><option value="bank">Bank transfer</option><option value="card">Card</option><option value="upi">UPI</option><option value="cash">Cash</option><option value="other">Other</option></select></div><div><label class="label">Reference</label><input v-model="payment.reference_number" class="field" placeholder="Optional transaction reference"/></div></div><p v-if="error" class="mt-3 text-xs text-rose-200">{{ error }}</p><button class="btn-primary mt-5 w-full" :disabled="workflowBusy"><LoaderCircle v-if="workflowBusy" :size="15" class="animate-spin"/>{{ workflowBusy ? 'Saving…' : 'Confirm payment' }}</button></form></div></Teleport>
        <Teleport to="body"><div v-if="movementOpen" class="fixed inset-0 z-[80] flex items-center justify-center p-4"><div class="absolute inset-0 bg-black/70 backdrop-blur-sm" @click="movementOpen = false"></div><form class="glass relative z-10 w-full max-w-md rounded-2xl p-5" @submit.prevent="submitMovement"><div class="flex items-center justify-between"><div><p class="eyebrow">Inventory workflow</p><h2 class="mt-1 text-xl font-semibold">Update stock</h2></div><button type="button" class="icon-btn" @click="movementOpen = false"><X :size="16"/></button></div><p class="mt-3 text-xs text-[#8eb8aa]">{{ selected?.name }} · current {{ selected?.quantity }} {{ selected?.unit }}</p><div class="mt-5 space-y-4"><div><label class="label">Movement</label><select v-model="movement.movement_type" class="field"><option value="stock_in">Stock in</option><option value="stock_out">Stock out</option></select></div><div><label class="label">Quantity</label><input v-model="movement.quantity" class="field" type="number" min="0.01" step="0.01" required/></div><div><label class="label">Movement date</label><input v-model="movement.movement_date" class="field" type="date" required/></div><div><label class="label">Unit price</label><input v-model="movement.unit_price" class="field" type="number" min="0" step="0.01"/></div><div><label class="label">Notes</label><textarea v-model="movement.notes" class="field" rows="3"/></div></div><p v-if="error" class="mt-3 text-xs text-rose-200">{{ error }}</p><button class="btn-primary mt-5 w-full" :disabled="workflowBusy"><LoaderCircle v-if="workflowBusy" :size="15" class="animate-spin"/>{{ workflowBusy ? 'Saving…' : 'Save movement' }}</button></form></div></Teleport>
    </div>
